import{_ as n,V as s,W as a,Z as t}from"./framework-828e3e61.js";const e={},p=t(`<h1 id="jackson-ignore-properties" tabindex="-1"><a class="header-anchor" href="#jackson-ignore-properties" aria-hidden="true">#</a> jackson ignore properties</h1><h2 id="_1-概述" tabindex="-1"><a class="header-anchor" href="#_1-概述" aria-hidden="true">#</a> <strong>1. 概述</strong></h2><p>本教程将展示如何在使用 Jackson 2.x<strong>将对象序列化为 JSON 时忽略某些字段。</strong></p><p>当 Jackson 默认值不够并且我们需要精确控制序列化为 JSON 的内容时，这非常有用 - 并且有多种方法可以忽略属性。</p><h2 id="_2-忽略类级别的字段" tabindex="-1"><a class="header-anchor" href="#_2-忽略类级别的字段" aria-hidden="true">#</a> <strong>2. 忽略类级别的字段</strong></h2><p>**我们可以使用@JsonIgnoreProperties注解并按名称指定字段，**在类级别忽略特定字段：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@JsonIgnoreProperties</span><span class="token punctuation">(</span>value <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token string">&quot;intValue&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">MyDto</span> <span class="token punctuation">{</span>

    <span class="token keyword">private</span> <span class="token class-name">String</span> stringValue<span class="token punctuation">;</span>
    <span class="token keyword">private</span> <span class="token keyword">int</span> intValue<span class="token punctuation">;</span>
    <span class="token keyword">private</span> <span class="token keyword">boolean</span> booleanValue<span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token class-name">MyDto</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">super</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// standard setters and getters are not shown</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>我们现在可以测试一下，在将对象写入 JSON 后，该字段确实不是输出的一部分：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">givenFieldIsIgnoredByName_whenDtoIsSerialized_thenCorrect</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
  <span class="token keyword">throws</span> <span class="token class-name">JsonParseException</span><span class="token punctuation">,</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
 
    <span class="token class-name">ObjectMapper</span> mapper <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ObjectMapper</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">MyDto</span> dtoObject <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MyDto</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">String</span> dtoAsString <span class="token operator">=</span> mapper<span class="token punctuation">.</span><span class="token function">writeValueAsString</span><span class="token punctuation">(</span>dtoObject<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token function">assertThat</span><span class="token punctuation">(</span>dtoAsString<span class="token punctuation">,</span> <span class="token function">not</span><span class="token punctuation">(</span><span class="token function">containsString</span><span class="token punctuation">(</span><span class="token string">&quot;intValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-在字段级别忽略字段" tabindex="-1"><a class="header-anchor" href="#_3-在字段级别忽略字段" aria-hidden="true">#</a> <strong>3.在字段级别忽略字段</strong></h2><p><strong>我们还可以直接通过字段上的</strong>@JsonIgnore注解直接忽略字段：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">MyDto</span> <span class="token punctuation">{</span>

    <span class="token keyword">private</span> <span class="token class-name">String</span> stringValue<span class="token punctuation">;</span>
    <span class="token annotation punctuation">@JsonIgnore</span>
    <span class="token keyword">private</span> <span class="token keyword">int</span> intValue<span class="token punctuation">;</span>
    <span class="token keyword">private</span> <span class="token keyword">boolean</span> booleanValue<span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token class-name">MyDto</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">super</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// standard setters and getters are not shown</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>我们现在可以测试<em>intValue</em>字段确实不是序列化 JSON 输出的一部分：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">givenFieldIsIgnoredDirectly_whenDtoIsSerialized_thenCorrect</span><span class="token punctuation">(</span><span class="token punctuation">)</span> 
  <span class="token keyword">throws</span> <span class="token class-name">JsonParseException</span><span class="token punctuation">,</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
 
    <span class="token class-name">ObjectMapper</span> mapper <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ObjectMapper</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">MyDto</span> dtoObject <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MyDto</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">String</span> dtoAsString <span class="token operator">=</span> mapper<span class="token punctuation">.</span><span class="token function">writeValueAsString</span><span class="token punctuation">(</span>dtoObject<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token function">assertThat</span><span class="token punctuation">(</span>dtoAsString<span class="token punctuation">,</span> <span class="token function">not</span><span class="token punctuation">(</span><span class="token function">containsString</span><span class="token punctuation">(</span><span class="token string">&quot;intValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-按类型忽略所有字段" tabindex="-1"><a class="header-anchor" href="#_4-按类型忽略所有字段" aria-hidden="true">#</a> <strong>4.按类型忽略所有字段</strong></h2><p>最后，我们可以使用**@JsonIgnoreType**注解来忽略指定类型的所有字段。如果我们控制类型，那么我们可以直接注解类：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@JsonIgnoreType</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">SomeType</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>然而，通常情况下，我们无法控制类本身。在这种情况下，<strong>我们可以充分利用Jackson mixin。</strong></p><p>首先，我们为要忽略的类型定义一个 MixIn，并使用*@JsonIgnoreType*对其进行注解：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@JsonIgnoreType</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">MyMixInForIgnoreType</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>然后我们注册该 mixin 以在编组期间替换（并忽略）所有<em>String[]类型：</em></p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code>mapper<span class="token punctuation">.</span><span class="token function">addMixInAnnotations</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token class-name">MyMixInForIgnoreType</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>此时，所有 String 数组都将被忽略，而不是编组为 JSON：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">final</span> <span class="token keyword">void</span> <span class="token function">givenFieldTypeIsIgnored_whenDtoIsSerialized_thenCorrect</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
  <span class="token keyword">throws</span> <span class="token class-name">JsonParseException</span><span class="token punctuation">,</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
 
    <span class="token class-name">ObjectMapper</span> mapper <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ObjectMapper</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    mapper<span class="token punctuation">.</span><span class="token function">addMixIn</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token class-name">MyMixInForIgnoreType</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">MyDtoWithSpecialField</span> dtoObject <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MyDtoWithSpecialField</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    dtoObject<span class="token punctuation">.</span><span class="token function">setBooleanValue</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">String</span> dtoAsString <span class="token operator">=</span> mapper<span class="token punctuation">.</span><span class="token function">writeValueAsString</span><span class="token punctuation">(</span>dtoObject<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token function">assertThat</span><span class="token punctuation">(</span>dtoAsString<span class="token punctuation">,</span> <span class="token function">containsString</span><span class="token punctuation">(</span><span class="token string">&quot;intValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>dtoAsString<span class="token punctuation">,</span> <span class="token function">containsString</span><span class="token punctuation">(</span><span class="token string">&quot;booleanValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>dtoAsString<span class="token punctuation">,</span> <span class="token function">not</span><span class="token punctuation">(</span><span class="token function">containsString</span><span class="token punctuation">(</span><span class="token string">&quot;stringValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这是我们的 DTO：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">MyDtoWithSpecialField</span> <span class="token punctuation">{</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> stringValue<span class="token punctuation">;</span>
    <span class="token keyword">private</span> <span class="token keyword">int</span> intValue<span class="token punctuation">;</span>
    <span class="token keyword">private</span> <span class="token keyword">boolean</span> booleanValue<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意：从2.5版本开始，我们似乎无法使用此方法来忽略原始数据类型，但我们可以将其用于自定义数据类型和数组。</p><h2 id="_5-使用过滤器忽略字段" tabindex="-1"><a class="header-anchor" href="#_5-使用过滤器忽略字段" aria-hidden="true">#</a> <strong>5.使用过滤器忽略字段</strong></h2><p>最后，<strong>我们还可以使用过滤器来忽略</strong>Jackson 中的特定字段。</p><p>首先，我们需要在 Java 对象上定义过滤器：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@JsonFilter</span><span class="token punctuation">(</span><span class="token string">&quot;myFilter&quot;</span><span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">MyDtoWithFilter</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>然后我们定义一个简单的过滤器，它将忽略<em>intValue</em>字段：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">SimpleBeanPropertyFilter</span> theFilter <span class="token operator">=</span> <span class="token class-name">SimpleBeanPropertyFilter</span>
  <span class="token punctuation">.</span><span class="token function">serializeAllExcept</span><span class="token punctuation">(</span><span class="token string">&quot;intValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">FilterProvider</span> filters <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">SimpleFilterProvider</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">addFilter</span><span class="token punctuation">(</span><span class="token string">&quot;myFilter&quot;</span><span class="token punctuation">,</span> theFilter<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>现在我们可以序列化该对象并确保JSON 输出中不存在<em>intValue字段：</em></p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">final</span> <span class="token keyword">void</span> <span class="token function">givenTypeHasFilterThatIgnoresFieldByName_whenDtoIsSerialized_thenCorrect</span><span class="token punctuation">(</span><span class="token punctuation">)</span> 
  <span class="token keyword">throws</span> <span class="token class-name">JsonParseException</span><span class="token punctuation">,</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
 
    <span class="token class-name">ObjectMapper</span> mapper <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ObjectMapper</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">SimpleBeanPropertyFilter</span> theFilter <span class="token operator">=</span> <span class="token class-name">SimpleBeanPropertyFilter</span>
      <span class="token punctuation">.</span><span class="token function">serializeAllExcept</span><span class="token punctuation">(</span><span class="token string">&quot;intValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">FilterProvider</span> filters <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">SimpleFilterProvider</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
      <span class="token punctuation">.</span><span class="token function">addFilter</span><span class="token punctuation">(</span><span class="token string">&quot;myFilter&quot;</span><span class="token punctuation">,</span> theFilter<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">MyDtoWithFilter</span> dtoObject <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MyDtoWithFilter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">String</span> dtoAsString <span class="token operator">=</span> mapper<span class="token punctuation">.</span><span class="token function">writer</span><span class="token punctuation">(</span>filters<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">writeValueAsString</span><span class="token punctuation">(</span>dtoObject<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token function">assertThat</span><span class="token punctuation">(</span>dtoAsString<span class="token punctuation">,</span> <span class="token function">not</span><span class="token punctuation">(</span><span class="token function">containsString</span><span class="token punctuation">(</span><span class="token string">&quot;intValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>dtoAsString<span class="token punctuation">,</span> <span class="token function">containsString</span><span class="token punctuation">(</span><span class="token string">&quot;booleanValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>dtoAsString<span class="token punctuation">,</span> <span class="token function">containsString</span><span class="token punctuation">(</span><span class="token string">&quot;stringValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>dtoAsString<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,35),o=[p];function c(i,l){return s(),a("div",null,o)}const r=n(e,[["render",c],["__file","Jackson-Ignore-Properties.html.vue"]]);export{r as default};
